const LOGO_URL = "data:image/png;base64,";

function svgAvatar(initials, bg) {
  const svg = `<svg xmlns="http://www.w3.org/2000/svg" width="150" height="150"><rect width="150" height="150" rx="75" fill="${bg}"/><text x="75" y="96" text-anchor="middle" font-family="Georgia, 'Times New Roman', serif" font-weight="600" font-size="54" fill="#ffffff">${initials}</text></svg>`;
  return `data:image/svg+xml,${encodeURIComponent(svg)}`;
}

function svgThumb(emoji, bg) {
  const svg = `<svg xmlns="http://www.w3.org/2000/svg" width="200" height="200"><rect width="200" height="200" rx="28" fill="${bg}"/><text x="100" y="128" text-anchor="middle" font-size="88">${emoji}</text></svg>`;
  return `data:image/svg+xml,${encodeURIComponent(svg)}`;
}

