/* Generates a unique illustrated "face" avatar per person, entirely inline (no
   network calls, so it always renders). Seeded off the person's name so the
   same person always gets the same look, and different people look different. */
function hashSeed(str) {
  let h = 0;
  for (let i = 0; i < str.length; i++) { h = (h * 31 + str.charCodeAt(i)) >>> 0; }
  return h;
}

/* Generates a unique illustrated "face" avatar per person, entirely inline (no
   network calls, so it always renders reliably in any preview/sandbox). Seeded off
   the person's name so the same person always gets the same look, and different
   people look different. Gender param nudges the hairstyle pool for a more
   plausible match to the demo name, purely for visual variety. */
function personAvatar(seed, gender) {
  const h = hashSeed(seed);
  const pick = (arr, offset = 0) => arr[(h >>> offset) % arr.length];

  const bgPairs = [
    ["#8B70F2", "#5A3FC0"], ["#F0B84C", "#C4831C"], ["#5FBE82", "#2E8A54"],
    ["#E8746B", "#B8443C"], ["#4FC3F7", "#1E88C7"], ["#BA68C8", "#8A3B9C"],
    ["#4DB6AC", "#1F857A"], ["#F06292", "#C13564"], ["#9575CD", "#634B9E"],
    ["#FF8A65", "#D85A32"], ["#7986CB", "#4A5799"], ["#4DD0E1", "#1FA0B2"],
  ];
  const skinTones = ["#F4C9A8", "#E8B48C", "#D89A6E", "#C17F52", "#9B6440", "#7A4B30"];
  const hairColors = ["#2B1B12", "#4A3220", "#6B4423", "#8C5A2E", "#A67C42", "#1A1A1A", "#5C3D2E", "#7A5A3A"];
  const femaleHairStyles = [
    // long / shoulder
    (skin, hair) => `<path d="M34 100 Q28 40 75 30 Q122 40 116 100 L108 100 Q112 55 75 46 Q38 55 42 100 Z" fill="${hair}"/><path d="M36 58 Q34 28 75 26 Q116 28 114 58 Q108 38 75 36 Q42 38 36 58 Z" fill="${hair}"/>`,
    // bun
    (skin, hair) => `<path d="M38 60 Q36 30 75 28 Q114 30 112 60 Q108 42 75 40 Q42 42 38 60 Z" fill="${hair}"/><circle cx="75" cy="20" r="12" fill="${hair}"/>`,
    // curly / afro
    (skin, hair) => `<circle cx="45" cy="42" r="15" fill="${hair}"/><circle cx="60" cy="30" r="17" fill="${hair}"/><circle cx="78" cy="26" r="18" fill="${hair}"/><circle cx="96" cy="30" r="17" fill="${hair}"/><circle cx="108" cy="44" r="15" fill="${hair}"/>`,
    // side part, longer
    (skin, hair) => `<path d="M34 90 Q30 30 78 26 Q120 28 114 88 L106 88 Q110 46 78 40 Q46 40 40 86 Z" fill="${hair}"/>`,
  ];
  const maleHairStyles = [
    // short crop
    (skin, hair) => `<path d="M38 62 Q38 30 75 28 Q112 30 112 62 L112 50 Q112 34 75 32 Q38 34 38 50 Z" fill="${hair}"/>`,
    // side part
    (skin, hair) => `<path d="M36 60 Q34 26 78 26 Q116 28 114 58 Q108 42 82 40 Q52 38 38 54 Z" fill="${hair}"/>`,
    // curly / textured
    (skin, hair) => `<circle cx="48" cy="44" r="13" fill="${hair}"/><circle cx="62" cy="32" r="15" fill="${hair}"/><circle cx="78" cy="28" r="16" fill="${hair}"/><circle cx="94" cy="32" r="15" fill="${hair}"/><circle cx="106" cy="46" r="13" fill="${hair}"/>`,
    // bald / short buzz
    (skin, hair) => `<path d="M40 52 Q40 34 75 33 Q110 34 110 52 Q110 44 75 42 Q40 44 40 52 Z" fill="${hair}" opacity="0.85"/>`,
  ];
  const hairStyles = gender === "men" ? maleHairStyles : gender === "women" ? femaleHairStyles : [...femaleHairStyles, ...maleHairStyles];

  const [bgA, bgB] = pick(bgPairs, 0);
  const skin = pick(skinTones, 3);
  const hair = pick(hairColors, 6);
  const hairPath = pick(hairStyles, 9)(skin, hair);
  const gradId = `g${h}`;

  const svg = `<svg xmlns="http://www.w3.org/2000/svg" width="150" height="150" viewBox="0 0 150 150">
    <defs>
      <linearGradient id="${gradId}" x1="0" y1="0" x2="1" y2="1">
        <stop offset="0%" stop-color="${bgA}"/>
        <stop offset="100%" stop-color="${bgB}"/>
      </linearGradient>
    </defs>
    <rect width="150" height="150" rx="75" fill="url(#${gradId})"/>
    <circle cx="75" cy="90" r="34" fill="${skin}"/>
    <circle cx="75" cy="66" r="26" fill="${skin}"/>
    <circle cx="63" cy="64" r="3" fill="#2A2148"/>
    <circle cx="87" cy="64" r="3" fill="#2A2148"/>
    <path d="M64 76 Q75 82 86 76" stroke="#2A2148" stroke-width="2.5" fill="none" stroke-linecap="round"/>
    ${hairPath}
  </svg>`;
  return `data:image/svg+xml,${encodeURIComponent(svg)}`;
}

