                        <>
                          <label style={{ fontSize: 12.5, color: COLORS.inkSoft }}>Instructor
                            <input value={storeForm.instructor} onChange={(e) => setStoreForm((f) => ({ ...f, instructor: e.target.value }))} style={{ ...inputStyle, display: "block", marginTop: 4, width: "100%" }} placeholder="e.g. Dr. Aris Thorne" />
                          </label>
                          <label style={{ fontSize: 12.5, color: COLORS.inkSoft }}>Duration
                            <input value={storeForm.duration} onChange={(e) => setStoreForm((f) => ({ ...f, duration: e.target.value }))} style={{ ...inputStyle, display: "block", marginTop: 4, width: "100%" }} placeholder="e.g. 5h 20m or 8 Weeks · Beginner Friendly" />
                          </label>
                        </>
